[
  {
    "version": "v0.9",
    "createSurface": {
      "surfaceId": "project-timeline-surface",
      "catalogId": "https://genui.local/specification/v0_9/standard_catalog.json"
    }
  },
  {
    "version": "v0.9",
    "updateComponents": {
      "surfaceId": "project-timeline-surface",
      "components": [
        {
          "id": "root",
          "type": "Column",
          "properties": {
            "spacing": "medium"
          },
          "children": [
            "title_text",
            "details_row",
            "assumptions_card",
            "divider",
            "phases_title",
            "project_timeline"
          ]
        },
        {
          "id": "title_text",
          "type": "Text",
          "properties": {
            "text": "Project Timeline: Mobile Application Development",
            "style": "title"
          }
        },
        {
          "id": "details_row",
          "type": "Row",
          "properties": {
            "spacing": "medium",
            "horizontalAlignment": "spaceBetween"
          },
          "children": [
            "start_date_text",
            "end_date_text",
            "duration_text"
          ]
        },
        {
          "id": "start_date_text",
          "type": "Text",
          "properties": {
            "text": "**Start Date:** 2024-11-01",
            "style": "body"
          }
        },
        {
          "id": "end_date_text",
          "type": "Text",
          "properties": {
            "text": "**End Date:** 2025-02-15",
            "style": "body"
          }
        },
        {
          "id": "duration_text",
          "type": "Text",
          "properties": {
            "text": "**Total Duration:** ~15 weeks (106 days)",
            "style": "body"
          }
        },
        {
          "id": "assumptions_card",
          "type": "Card",
          "properties": {
            "title": "Assumptions"
          },
          "children": [
            "assumptions_list"
          ]
        },
        {
          "id": "assumptions_list",
          "type": "List",
          "children": [
            {
              "id": "assumption_1",
              "type": "ListItem",
              "properties": {
                "primaryText": "The project follows an agile-like methodology with iterative development and overlapping phases where possible."
              }
            },
            {
              "id": "assumption_2",
              "type": "ListItem",
              "properties": {
                "primaryText": "Team availability and resources are consistent throughout the project duration."
              }
            },
            {
              "id": "assumption_3",
              "type": "ListItem",
              "properties": {
                "primaryText": "Requirements are largely stable after initial definition, allowing for efficient design and development."
              }
            },
            {
              "id": "assumption_4",
              "type": "ListItem",
              "properties": {
                "primaryText": "The scope of the mobile application is moderate, allowing for completion within 3.5 months."
              }
            }
          ]
        },
        {
          "id": "divider",
          "type": "Divider"
        },
        {
          "id": "phases_title",
          "type": "Text",
          "properties": {
            "text": "Project Phases and Key Activities",
            "style": "headline"
          }
        },
        {
          "id": "project_timeline",
          "type": "Timeline",
          "children": [
            "phase_1_design",
            "phase_2_frontend"
          ]
        },
        {
          "id": "phase_1_design",
          "type": "TimelineItem",
          "properties": {
            "title": "UI/UX Design",
            "icon": "/design.png"
          },
          "children": [
            "phase_1_details",
            "phase_1_activities"
          ]
        },
        {
          "id": "phase_1_details",
          "type": "Text",
          "properties": {
            "text": "**Duration:** 2024-11-01 to 2024-12-06 (approx. 5 weeks, overlapping)",
            "style": "caption"
          }
        },
        {
          "id": "phase_1_activities",
          "type": "List",
          "children": [
            {
              "id": "p1_act_1",
              "type": "ListItem",
              "properties": {
                "primaryText": "Requirement gathering and analysis"
              }
            },
            {
              "id": "p1_act_2",
              "type": "ListItem",
              "properties": {
                "primaryText": "User research and persona creation"
              }
            },
            {
              "id": "p1_act_3",
              "type": "ListItem",
              "properties": {
                "primaryText": "Wireframing and user flow mapping"
              }
            },
            {
              "id": "p1_act_4",
              "type": "ListItem",
              "properties": {
                "primaryText": "Low-fidelity and high-fidelity mockups"
              }
            },
            {
              "id": "p1_act_5",
              "type": "ListItem",
              "properties": {
                "primaryText": "Prototyping and user testing"
              }
            },
            {
              "id": "p1_act_6",
              "type": "ListItem",
              "properties": {
                "primaryText": "Design system creation and finalization"
              }
            }
          ]
        },
        {
          "id": "phase_2_frontend",
          "type": "TimelineItem",
          "properties": {
            "title": "Frontend Development",
            "icon": "/frontend.png"
          },
          "children": [
            "phase_2_details",
            "phase_2_activities"
          ]
        },
        {
          "id": "phase_2_details",
          "type": "Text",
          "properties": {
            "text": "**Duration:** 2024-11-25 to 2025-01-17 (approx. 8 weeks, overlapping)",
            "style": "caption"
          }
        },
        {
          "id": "phase_2_activities",
          "type": "List",
          "children": [
            {
              "id": "p2_act_1",
              "type": "ListItem",
              "properties": {
                "primaryText": "Development environment setup and tooling configuration"
              }
            }
          ]
        }
      ]
    }
  }
]
